{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    allocations = [0] * n
    total_min = 0
    total_cap = 0
    for i, seg in enumerate(segments):
        min_val = seg['minimum']
        cap = seg['capacity']
        if min_val > cap:
            raise ValueError(f"Minimum {min_val} exceeds capacity {cap} for segment {seg['name']}")
        allocations[i] = min_val
        total_min += min_val
        total_cap += cap
    if budget < total_min:
        raise ValueError(f"Budget {budget} is less than total minimum {total_min}")
    if budget > total_cap:
        raise ValueError(f"Budget {budget} exceeds total capacity {total_cap}")
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_value = -1.0
        # iterate in original order for stable tie-break
        for i in range(n):
            seg = segments[i]
            if allocations[i] < seg['capacity']:
                # next allocated position = current allocations[i] + 1
                value = seg['importance'] / (allocations[i] + 1)
                if value > best_value:
                    best_value = value
                    best_idx = i
        if best_idx == -1:
            # should not happen because remaining>0 and total_cap >= budget ensures capacity
            raise ValueError("No capacity left but budget not exhausted")
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {}
    for i, seg in enumerate(segments):
        by_name[seg['name']] = allocations[i]
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": budget
    }"
}
